def main():
    assert set(DATA.keys()) == set(IDS), "id set mismatch"
    assert len(DATA) == 20, "count mismatch"
    os.makedirs(BASE, exist_ok=True)
    n = 0
    for cid in IDS:
        d = DATA[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"],
               "basis": d["basis"], "confidence": d["confidence"], "trigger": d["trigger"]}
        with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20
    print("written", n)

if __name__ == "__main__":
    main()
